from pathlib import Path
import json, html
O=Path(__file__).resolve().parent
m=json.loads((O/'manifest.json').read_text())
data=json.dumps(m,ensure_ascii=False).replace('</','<\\/')
template='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MeDIAuto AI · 기능별 이미지 보드</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5fa;color:#17243c;font:15px/1.65 system-ui,-apple-system,sans-serif}button,a{font:inherit}button{cursor:pointer}header{background:#17243c;color:white;padding:32px 5vw}header small{color:#b4c2dc;letter-spacing:2px}h1{font-size:30px;margin:5px 0}header p{margin:0;color:#c6d1e5}.layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:28px;max-width:1600px;margin:30px auto;padding:0 28px}nav{min-width:0;display:flex;flex-direction:column;gap:8px;align-self:start;position:sticky;top:20px}nav button{text-align:left;border:1px solid #dce2ee;background:white;border-radius:10px;padding:12px 15px;color:#42516c}nav button.active{background:#5146bf;border-color:#5146bf;color:white}nav small{display:block;font-size:11px;opacity:.7}.panel{min-width:0;background:white;border:1px solid #e0e5ef;border-radius:16px;padding:24px}.eyebrow{color:#7765c4;font-weight:650;font-size:12px;letter-spacing:1px}h2{margin:3px 0;font-size:27px}.subtitle{color:#66748b;margin:0 0 18px}.stage{background:#ebedf6;aspect-ratio:2560/1272;border:1px solid #e5e9f2;border-radius:10px;overflow:hidden;position:relative}.stage img{display:block;width:100%;height:100%;object-fit:contain}.stage img.enter{animation:arrive .6s ease-out}.stage img.zoom{animation:zoom 3.5s ease-in-out forwards}@keyframes arrive{from{opacity:.3}to{opacity:1}}@keyframes zoom{from{transform:scale(1)}to{transform:scale(1.06)}}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:16px 0}.controls button,.controls a{border:1px solid #d7deeb;background:white;color:#334663;border-radius:8px;padding:7px 13px;text-decoration:none}.controls .primary{background:#5146bf;color:white;border-color:#5146bf}.controls a[hidden]{display:none}#label{margin-left:auto;font-size:13px;color:#61718b}.frames{display:flex;gap:12px;overflow-x:auto;padding:3px 0 14px}.frame{min-width:155px;max-width:200px;flex:1;border:2px solid transparent;border-radius:9px;background:#f6f7fb;padding:5px;text-align:left;color:#344560}.frame.active{border-color:#7765c4}.frame img{width:100%;display:block;border-radius:5px}.frame span{display:block;padding:5px;font-size:12px}.note{background:#f5f3fc;border-radius:9px;padding:15px 18px;font-size:13px;color:#50496c}.note strong{display:block;margin-bottom:5px}details{margin-top:22px;color:#647087;font-size:13px}summary{cursor:pointer}footer{padding:0 28px 30px;max-width:1600px;margin:auto;color:#6a768d;font-size:12px}.filelinks a{color:#5146bf}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #db8e30;outline-offset:3px}@media(max-width:850px){.layout{grid-template-columns:minmax(0,1fr);padding:0 14px;gap:14px}nav{position:static;flex-direction:row;overflow-x:auto}nav button{min-width:155px}.panel{padding:15px}header{padding:25px}.controls{gap:6px}#label{width:100%;margin:0}}@media(prefers-reduced-motion:reduce){.stage img.enter,.stage img.zoom{animation:none}}
</style>
<header><small>PRODUCT VISUAL ASSETS / 01</small><h1>MeDIAuto AI</h1><p>기능별 이미지 보드 · 8개 장면 · 전체 화면 25장 + 상세 컷 18장</p></header>
<div class="layout"><nav aria-label="기능 선택" id="nav"></nav><main class="panel"><div class="eyebrow" id="scene-number"></div><h2 id="title"></h2><p class="subtitle" id="subtitle"></p><div class="stage"><img id="hero" alt=""></div><div class="controls"><button class="primary" id="play">▶ 순서 미리보기</button><button id="mode" aria-pressed="false">상세 컷 보기</button><a id="full-link" download>전체 PNG</a><a id="detail-link" download>상세 PNG</a><span id="label"></span></div><div class="frames" id="frames"></div><div class="note"><strong>애니메이션 구성 메모</strong><span id="motion"></span></div><details><summary>자료 출처와 추가 촬영 목록</summary><p>기존 실제 제품의 비식별 화면을 사용했습니다. 상세 컷은 기존 이미지를 Chromium에 표시해 촬영했습니다. 현재 실행 중인 앱을 새로 촬영한 자료는 아닙니다. 순서 미리보기는 정지 화면의 전환 연출이며 실제 작업을 재생한 영상이 아닙니다.</p><ul id="missing"></ul><p>기존 비식별 처리를 유지했습니다. 외부 공개 전 파일명·영상 사용 권한·남은 식별 정보를 확인해 주세요.</p><div class="filelinks"><a href="manifest.json">이미지 목록·출처·권장 타이밍 JSON</a> · <a href="contact-sheet.html">전체 화면 한눈에 보기</a></div></details></main></div><footer>전체 화면은 원본 해상도 2560 × 1272 PNG입니다. 상세 컷은 좌우 패널 또는 주변 여백을 줄인 브라우저 캡처입니다. 제품명: MeDIAuto AI.</footer>
<script>const data=__DATA__;let si=0,fi=0,detail=false,timer=null;const $=id=>document.getElementById(id);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function stop(){clearInterval(timer);timer=null;$('play').textContent='▶ 순서 미리보기'}function showFrame(i){fi=i;const f=data.scenes[si].frames[fi];$('hero').src=detail&&f.detail?f.detail:f.full;$('hero').alt=f.label;$('hero').className='';void $('hero').offsetWidth;$('hero').className=timer&&!reduced?'zoom':'enter';$('label').textContent=(fi+1)+' / '+data.scenes[si].frames.length+' · '+f.label;$('full-link').href=f.full;$('detail-link').hidden=!f.detail;$('detail-link').href=f.detail||f.full;$('mode').disabled=!f.detail;$('mode').textContent=detail?'전체 화면 보기':'상세 컷 보기';$('mode').setAttribute('aria-pressed',String(detail));[...$('frames').children].forEach((n,j)=>{n.classList.toggle('active',j===fi);n.setAttribute('aria-pressed',String(j===fi))})}function selectScene(i){stop();si=i;fi=0;detail=false;const s=data.scenes[i];$('scene-number').textContent='SCENE '+String(i+1).padStart(2,'0')+' / 08';$('title').textContent=s.title;$('subtitle').textContent=s.subtitle;$('motion').textContent=s.animation;[...$('nav').children].forEach((n,j)=>{n.classList.toggle('active',i===j);n.setAttribute('aria-pressed',String(i===j))});$('frames').replaceChildren();s.frames.forEach((f,j)=>{const b=document.createElement('button');b.className='frame';const img=document.createElement('img');img.src=f.preview;img.alt='';const span=document.createElement('span');span.textContent=f.label;b.append(img,span);b.onclick=()=>{stop();showFrame(j)};$('frames').append(b)});showFrame(0)}data.scenes.forEach((s,i)=>{const b=document.createElement('button');const small=document.createElement('small');small.textContent='SCENE '+String(i+1).padStart(2,'0');const span=document.createElement('span');span.textContent=s.title;b.append(small,span);b.onclick=()=>selectScene(i);$('nav').append(b)});data.additional_live_captures_needed.forEach(t=>{const li=document.createElement('li');li.textContent=t;$('missing').append(li)});$('mode').onclick=()=>{detail=!detail;showFrame(fi)};$('play').onclick=()=>{if(timer){stop();return}timer=setInterval(()=>showFrame((fi+1)%data.scenes[si].frames.length),3500);$('play').textContent='Ⅱ 일시정지';showFrame(fi)};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});selectScene(0);</script></html>'''
(O/'index.html').write_text(template.replace('__DATA__',data),encoding='utf-8')
parts=['<!doctype html><html lang="ko"><meta charset="utf-8"><title>MeDIAuto AI · 전체 캡처</title><style>body{font:15px/1.5 system-ui;background:#f3f5fa;color:#17243c;margin:36px}h1{margin-bottom:4px}p{color:#63718a}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{background:white;padding:10px;border-radius:8px;break-inside:avoid}.card img{width:100%;display:block}.card span{display:block;padding:8px 0 0;font-size:12px}a{color:inherit;text-decoration:none}h2{font-size:19px;margin:30px 0 10px}@media(max-width:700px){.grid{grid-template-columns:1fr}}@media print{body{margin:10mm}.grid{grid-template-columns:repeat(3,1fr)}}</style><h1>MeDIAuto AI</h1><p>기존 실제 화면 기반 · 8개 기능 묶음 · 전체 PNG 25장 / 상세 PNG 18장</p><a href="index.html">← 기능별 미리보기</a>']
for s in m['scenes']:
 parts.append('<h2>'+html.escape(s['title'])+'</h2><div class="grid">')
 for f in s['frames']:
  parts.append('<a class="card" href="'+f['full']+'"><img src="'+f['preview']+'"><span>'+html.escape(f['label'])+'</span></a>')
 parts.append('</div>')
parts.append('</html>');(O/'contact-sheet.html').write_text(''.join(parts),encoding='utf-8')
print('Gallery and contact sheet created')
